				onInsertToNote={insertHandler}
				onNewEmbeddedChat={createNoteChat}
				onCreateEmbeddedChat={createNoteChatOnFirstMessage}
				onSelectEmbeddedChat={(chatId) => {
					if (!chatId || chatId === noteChatId) return;
